        vtop_msg_id?.let { w.int(it) }
        w.int(vdate)
        w.string(vmessage)
        ventities?.let { w.vector(it) { it.serialize(w) } }
        vmedia?.let { it.serialize(w) }
        vreply_markup?.let { it.serialize(w) }
        vreply_to?.let { it.serialize(w) }
        vrich_message?.let { it.serialize(w) }
        vchat_instance?.let { w.long(it) }
        vanchor_msg_id?.let { w.int(it) }
